    RAISE EXCEPTION 'production disabled scheduler and monitor predecessor required' USING ERRCODE='P7921'; END IF;
  IF (SELECT count(*) FROM jetnity_prod_import_scheduler.state_v1 WHERE singleton AND NOT enabled AND status='disabled')<>1
    OR EXISTS(SELECT 1 FROM jetnity_prod_import_scheduler.cycles_v1)
    OR EXISTS(SELECT 1 FROM jetnity_prod_import_scheduler.dispatches_v1)
    OR EXISTS(SELECT 1 FROM cron.job WHERE jobname IN ('jetnity-ch-de-prod-import-v1','jetnity-official-truth-production-guard-v1')) THEN
    RAISE EXCEPTION 'production scheduler must be unused and disabled before the core' USING ERRCODE='P7921'; END IF;
  FOR expected IN SELECT * FROM jsonb_to_recordset('[{"signature":"jetnity_prod_import_scheduler.preserve_request_v1()","name":"jetnity_prod_import_scheduler.preserve_request_v1","owner":"postgres","hash":"60af95f0d0646db2811a7121adc15bad39f5a2f37e8aca74420e0ab610277b5d","language":"plpgsql","definer":false,"volatile":"v","config":["search_path=pg_catalog"],"grantees":["postgres"]},{"signature":"jetnity_prod_import_scheduler.tick_v1()","name":"jetnity_prod_import_scheduler.tick_v1","owner":"postgres","hash":"ebc518fc18e8c5057941c1d65890171b510fa67138dc85023ac1d95195f6bb3a","language":"plpgsql","definer":false,"volatile":"v","config":["search_path=pg_catalog","statement_timeout=10s","lock_timeout=2s"],"grantees":["postgres"]},{"signature":"public.jetnity_production_import_status_v1()","name":"public.jetnity_production_import_status_v1","owner":"postgres","hash":"b765e150645674b43b30cbda0b4874b22eceedfd5973b93bcdbe2cf7fcb58599","language":"plpgsql","definer":true,"volatile":"v","config":["search_path=pg_catalog","statement_timeout=5s","lock_timeout=1s"],"grantees":["anon","postgres"]}]'::jsonb)
    AS bound(signature text,owner text,hash text,language text,definer boolean,volatile text,config jsonb,grantees jsonb) LOOP
    SELECT * INTO STRICT actual FROM pg_proc WHERE oid=to_regprocedure(expected.signature);
    SELECT jsonb_agg(role_name ORDER BY role_name) INTO actual_acl FROM (
      SELECT DISTINCT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS role_name
      FROM aclexplode(COALESCE(actual.proacl,acldefault('f',actual.proowner))) a
    ) allowed;
    IF actual.proowner<>'postgres'::regrole OR actual.prokind<>'f'
      OR actual.proleakproof OR actual.proisstrict OR actual.proretset OR actual.pronargs<>0
      OR actual.pronargdefaults<>0 OR actual.provariadic<>0 OR actual.proargnames IS NOT NULL
      OR actual.proparallel<>'u' OR actual.prosecdef<>expected.definer OR actual.provolatile::text<>expected.volatile
      OR (SELECT lanname FROM pg_language WHERE oid=actual.prolang)<>expected.language
      OR to_jsonb(actual.proconfig) IS DISTINCT FROM expected.config OR actual_acl IS DISTINCT FROM expected.grantees
      OR encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex')<>expected.hash
      OR EXISTS(SELECT 1 FROM aclexplode(COALESCE(actual.proacl,acldefault('f',actual.proowner))) a
        WHERE a.privilege_type<>'EXECUTE' OR a.is_grantable OR a.grantor<>actual.proowner) THEN
      RAISE EXCEPTION 'production exact scheduler function predecessor required' USING ERRCODE='P7921'; END IF;
  END LOOP;
END $production_scheduler_preflight$;

CREATE TEMP TABLE production_preserved(kind text PRIMARY KEY,value jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO pg_temp.production_preserved
SELECT 'relations',COALESCE(jsonb_object_agg(c.oid::text,to_jsonb(c)-ARRAY['relpages','reltuples','relallvisible','relfrozenxid','relminmxid']), '{}'::jsonb)
FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg\_%' ESCAPE '\';
INSERT INTO pg_temp.production_preserved
SELECT 'functions',COALESCE(jsonb_object_agg(p.oid::text,to_jsonb(p)), '{}'::jsonb)
FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg\_%' ESCAPE '\';
INSERT INTO pg_temp.production_preserved
SELECT 'namespaces',COALESCE(jsonb_object_agg(n.oid::text,to_jsonb(n)), '{}'::jsonb)
FROM pg_namespace n WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg\_%' ESCAPE '\';
INSERT INTO pg_temp.production_preserved
SELECT 'roles',COALESCE(jsonb_object_agg(r.oid::text,to_jsonb(r)-'rolpassword'), '{}'::jsonb) FROM pg_roles r;
INSERT INTO pg_temp.production_preserved
SELECT 'memberships',COALESCE(jsonb_object_agg(m.oid::text,to_jsonb(m)), '{}'::jsonb) FROM pg_auth_members m;
INSERT INTO pg_temp.production_preserved
SELECT 'database',(to_jsonb(d)-ARRAY['datfrozenxid','datminmxid'])
  ||jsonb_build_object('datacl',to_jsonb(COALESCE(d.datacl,acldefault('d',d.datdba)))) FROM pg_database d WHERE datname=current_database();
DO $production_cron_snapshot$
DECLARE value jsonb;
BEGIN
  IF to_regclass('cron.job') IS NOT NULL THEN
    EXECUTE 'SELECT COALESCE(jsonb_object_agg(jobid::text,to_jsonb(j)),''{}''::jsonb) FROM cron.job j' INTO value;
    INSERT INTO pg_temp.production_preserved VALUES('cron_jobs',value);
  END IF;
END $production_cron_snapshot$;

