    AND NOT official_v3_guard_private.allowed_owner_edge_v1(d.classid,d.objid,d.refobjid,d.deptype)
    AND NOT(d.dbid=(SELECT b.oid FROM pg_catalog.pg_database b WHERE b.datname=current_database())
