 VALUES('research-job:v3:74713fe665cab1a7603f6e93ab06b6a1d1964e83a69571b8cced0ff009032513',
 '{"methodId":"jetnity-destination-primary-ch-de-visa","revision":1,"methodDigest":"44ce02752da05796bef98c55b5099b81f915fe6b0975472e163721a06793bdb3","packageDigest":"0beb25db2e1f6e4c2c96d61ded30b59a8e06a32ed94498903fbeecc3b6f267e9"}'::jsonb,86400,64,256,0,0,clock_timestamp());

